      '【何を聞かれているか】\nシダ植物とコケ植物の、いちばん大きなちがいを答えます。\n\n【2つの共通点】\nまず似ているところを押さえます。どちらも「種子をつくらず、胞子でふえます」。花もさきません。だから同じ仲間だと思われがちです。\n\n【決定的なちがい】\nシダ植物には維管束（道管・師管）があり、コケ植物にはありません。\n\n【なぜこれが「いちばん大きな」ちがいなのか】\n維管束があるかないかで、その植物の生き方がまるごと決まってしまうからです。\n・シダ植物　……　根から吸った水を道管で体の上まで運べる。だから「根・茎・葉の区別があり、背を高くできる」。ワラビやゼンマイのように、人の背丈ほどになるものもある\n・コケ植物　……　運ぶ管がないので、体の表面から直接水を取りこむしかない。だから「根・茎・葉の区別がなく、背も低い」。いつも湿った場所にしか生えられない\n見た目の大きさのちがいも、生える場所のちがいも、もとをたどればこの1点から来ています。\n\n【答え】シダ植物は維管束（道管・師管）を持つが、コケ植物は持たない。\n\n【例】\nシダ植物　……　イヌワラビ、ゼンマイ、スギナ、ヘゴ\nコケ植物　……　スギゴケ、ゼニゴケ\n\n【まちがえやすいところ】\n・「胞子でふえるほうがコケ」と覚えてしまう。胞子でふえるのは両方です。見分けるのは維管束のほうです。\n・シダの葉の裏にある茶色いつぶつぶは、虫の卵ではなく胞子のうです。',
