    difficulty: 'basic',
    question: '心臓から出た血液が全身をめぐって心臓に戻る経路を体循環という。肺をめぐる経路を何というか。また体循環と肺循環で血液が通る心臓の部屋はどこか。',
    answer: '肺循環。体循環：左心室→全身→右心房。肺循環：右心室→肺→左心房。',
    hint: '心臓は4つの部屋（右心房・右心室・左心房・左心室）',
    explanation:
      '【何を聞かれているか】\n肺をめぐる血液の経路の名前と、体循環・肺循環がそれぞれ心臓のどの部屋から出て、どの部屋に戻るかを答えます。\n\n【心臓は4つの部屋でできている】\n右心房・右心室・左心房・左心室の4つです。\n・心房　……　血液が戻ってくる部屋（入口）\n・心室　……　血液を送り出す部屋（出口）\n「房で受けて、室から出す」と覚えます。\n\n【2つの道すじ】\n・体循環　……　左心室 → 大動脈 → 全身 → 大静脈 → 右心房\n・肺循環　……　右心室 → 肺動脈 → 肺 → 肺静脈 → 左心房\n\n【なぜ2つに分かれているのか】\n血液には2つの仕事があります。「肺で酸素を受け取る」ことと「全身に酸素を配る」ことです。\nこの2つを1本の道でやろうとすると、酸素を受け取った血液と使い終わった血液が混ざってしまいます。道を2本に分け、心臓を左右に仕切ることで、「きれいな血液とよごれた血液が混ざらない」ようになっています。\n\n【答え】肺循環。体循環：左心室→全身→右心房。肺循環：右心室→肺→左心房。\n\n【動脈血・静脈血の注意】\n・動脈血（酸素が多い）……　肺静脈 と 大動脈 を流れる\n・静脈血（酸素が少ない）……　肺動脈 と 大静脈 を流れる\n「肺動脈には静脈血、肺静脈には動脈血」が流れます。名前と中身が逆になる、この2本だけが例外です。\n\n【なぜ逆になるのか】\n動脈・静脈という名前は、中身ではなく「向き」で決まっているからです。心臓から出ていく血管が動脈、心臓へ戻る血管が静脈。肺へ向かう血管は心臓から出ていくので肺動脈ですが、中を流れるのはこれから酸素をもらう静脈血なのです。\n\n【まちがえやすいところ】\n・左心室の壁がいちばん厚くなっています。全身という遠くまで血液を押し出すため、強い力が必要だからです。\n・「動脈＝きれいな血」と覚えてしまうと、肺動脈でつまずきます。名前は向きで決まる、と覚え直しましょう。',
