      '【何を聞かれているか】\n背骨のある動物（脊椎動物）を5つのなかまに分け、それぞれ例を1つずつ答えます。\n\n【何を手がかりに分けるのか】\n見分けるときは、次の3つを順に確かめます。\n① どこで呼吸するか（えら か 肺 か）\n② 体温が変わるか（変温 か 恒温 か）\n③ どうやって子をふやすか（卵 か 子 か。卵なら殻があるか）\nこの3つの組み合わせで、5つのなかまがきれいに分かれます。\n\n【5つのなかま】\n魚類（コイ）　　……　えら呼吸・変温・水中に殻のない卵\n両生類（カエル）……　子はえら、親は肺と皮膚・変温・水中にゼリー状の卵\nは虫類（ヘビ）　……　肺呼吸・変温・陸上に殻のある卵\n鳥類（スズメ）　……　肺呼吸・恒温・陸上にかたい殻の卵\nほ乳類（ヒト）　……　肺呼吸・恒温・子をうむ（胎生）\n\n【答え】魚類（コイ）、両生類（カエル）、爬虫類（ヘビ）、鳥類（スズメ）、哺乳類（ヒト）\n\n【なぜこの順に並べるのか】\n上から順に「水の中の暮らし」から「陸の暮らし」へ、少しずつ変わっていきます。\n・魚類はまるごと水の中\n・両生類は子が水、親が陸（だから「両方で生きる」で両生）\n・は虫類は卵に殻がついたので、水辺をはなれて陸で産めるようになった\n・鳥類とほ乳類は体温を一定に保てるので、寒い土地でも動ける\n「殻のある卵になったことと、体温を保てるようになったこと」が、陸で暮らすための2つの大きな変化です。\n\n【まちがえやすいところ】\n・クジラ・イルカ・コウモリをほ乳類でないと思ってしまう。肺で呼吸し、子をうんで乳で育てるので、すべてほ乳類です。\n・ペンギンは鳥類です。泳ぐからといって魚類ではありません。\n・カメは水の中にいても、肺で呼吸し殻のある卵を産むので は虫類です。\n・イモリ（両生類）とヤモリ（は虫類）を取りちがえやすい。イモリは水べにいて皮膚がしめっており、ヤモリは家のかべにいて皮膚がかさかさしています。',
    examFrequency: 'high',
