      '【何を聞かれているか】\nけんび鏡で観察を始めるとき、最初に選ぶ対物レンズの倍率です。\n\n【なぜ低い倍率から始めるのか】\n理由は2つあります。\n\n①見える範囲が広いから\n倍率を上げると、ものは大きく見えますが、そのぶん見える範囲はせまくなります。高い倍率でいきなり探すのは、望遠鏡をのぞいたまま鳥を探すようなもので、なかなか見つかりません。まず低い倍率で広く見わたして、見たいものを見つけ、それを真ん中に動かしてから倍率を上げます。\n\n②明るいから\n倍率を上げるほど、視野は暗くなります。低い倍率のほうが明るいので、何がどこにあるかが分かりやすいのです。\n\n【ステップでまとめると】\n1. いちばん低い倍率の対物レンズにする\n2. 反射鏡としぼりを動かして、明るく見えるようにする\n3. 横から見ながら、対物レンズとプレパラートをできるだけ近づける\n4. のぞきながら、対物レンズとプレパラートを遠ざける向きに調節ねじを回してピントを合わせる\n5. 見たいものを視野の真ん中に動かす\n6. レボルバーを回して高い倍率にする\n\n【答え】\nいちばん低い倍率の対物レンズ\n\n【確かめ】\nもし高い倍率から始めると、視野がせまく暗いので、プレパラートのどこを見ているのかが分からなくなります。実際にやってみると、低い倍率から始めたほうがずっと速く見つかることが分かります。\n\n【よくあるまちがい】\n・「よく見たいのだから高い倍率から」と考えてしまう。順番は逆です。\n・手順3と4を逆にしてしまう。のぞきながら近づけると、対物レンズがプレパラートにぶつかってガラスを割ってしまうことがあります。必ず「横から見て近づける→のぞきながら遠ざける」の順です。\n・倍率を上げたあとに、視野が暗くなったからといって対物レンズのせいにしてしまう。しぼりや反射鏡で明るさを調節します。',
