    question:
      '根から吸い上げられた水が、高いところにある葉まで届くのはなぜですか。葉のはたらきをもとに説明しなさい。',
    answer:
      '葉の気孔から水が水蒸気になって出ていく（蒸散）ので、その分だけくきの中の水が上へ引き上げられ、続けて根から新しい水が吸い上げられるから。',
    hint:
      '葉から水が水蒸気になって出ていくことを蒸散という。ストローで上から吸うと下の飲み物が上がってくるのと同じで、上でへった分だけ下から上がってくる。',
    explanation:
      '【何を聞かれているか】\n植物にはポンプもモーターもないのに、なぜ水が根から高い葉まで上がっていけるのか、という理由です。\n\n【まず、水の通り道を確かめる】\n根から吸った水は、根・くき・葉とつながった細い管（道管）の中を通ります。この管の中で、水は上から下までとぎれずにつながっています。ここが大事なところです。\n\n【ステップ1】葉から水が出ていく\n葉の裏には気孔という小さな穴がたくさんあります。ここから水が水蒸気になって空気中へ出ていきます。これを蒸散といいます。\n\n【ステップ2】へった分だけ、下から上がってくる\n水はとぎれずにつながっているので、いちばん上でへると、その分だけ下の水が引き上げられます。ストローで上から吸うと、コップの底の飲み物まで上がってくるのと同じしくみです。押し上げているのではなく、上から引かれていると考えるのがこの問題のポイントです。\n\n【ステップ3】根から新しい水が入る\n上へ引き上げられた分だけ根のあたりの水が足りなくなるので、根から新しい水が吸い上げられます。こうして、蒸散が続いているかぎり、水は止まらずに流れ続けます。\n\n【答え】\n葉の気孔から蒸散が起こり、その分だけ管の中の水が上へ引き上げられて、根から新しい水が吸い上げられるから。\n\n【確かめ】\n切った枝を色水にさして、葉のついたものと葉を全部取ったものをくらべると、葉のついたほうが色水をずっと速く吸い上げます。また、葉にとうめいなふくろをかぶせておくと、内側に水てきがついて、葉から水が出ていることが目で見て分かります。\n\n【よくあるまちがい】\n「根が水を押し上げている」と書いてしまう人が多いですが、それだけでは高い木のてっぺんまで届きません。主役は葉の蒸散です。もう1つ、気孔が葉の表ではなく裏に多いことも合わせて覚えておきましょう。',
    examFrequency: 'medium',
