    question:
      '人がはき出した息（はく息）には、吸いこむ空気（吸う息）とくらべて多くふくまれる気体が2つあります。それは何と何ですか。また、そのことを確かめる方法も答えなさい。',
    answer:
      '二酸化炭素と水蒸気。二酸化炭素は、はいた息を石灰水に通すと白くにごることで確かめられる。水蒸気は、冷たいガラスやかがみにはきかけると、水てきがついてくもることで確かめられる。',
    hint:
      '冬に息をはくと白く見えるのはなぜか、そして、息を石灰水に通すとどうなるかを思い出す。',
    explanation:
      '【何を聞かれているか】\nはく息に多くふくまれる気体を2つあげ、それぞれの確かめ方まで答える問題です。\n\n【なぜ気体の割合が変わるのか】\n人は、吸いこんだ空気の中の酸素を体に取り入れ、食べ物からとった養分と結びつけてエネルギーを取り出しています。このとき、二酸化炭素と水ができます。それをはく息としていっしょに出しているので、はく息では二酸化炭素と水蒸気がふえ、酸素は減ります。\n\n【気体の割合のちがい（およその値）】\n・酸素 …… 吸う息 約21％ → はく息 約17％（減る）\n・二酸化炭素 …… 吸う息 約0.04％ → はく息 約4％（大きくふえる）\n・水蒸気 …… はく息のほうがずっと多い\nちっ素（約78％）は体に取り入れられないので、ほとんど変わりません。ここもよく問われます。\n\n【確かめ方①：二酸化炭素】\nストローで石灰水の中に息をふきこみます。石灰水は二酸化炭素と反応して白くにごります。\nくらべるために、ふくろにためた空気を同じように通してみると、ほとんどにごりません。この差が「はく息のほうが二酸化炭素が多い」ことの証拠になります。\n\n【確かめ方②：水蒸気】\n冷たいガラスやかがみに息をはきかけると、表面がくもって水てきがつきます。はく息にふくまれていた水蒸気が、冷やされて水にもどったからです。\n冬に息が白く見えるのも同じ理由で、白く見えているのは水蒸気そのものではなく、冷やされてできた小さな水のつぶです。\n\n【答え】\n二酸化炭素と水蒸気。二酸化炭素は石灰水が白くにごることで、水蒸気は冷たいものがくもることで確かめられる。\n\n【確かめ】\n酸素が減っていることも確かめられます。ふくろにためたはく息の中では、ろうそくの火が空気中より早く消えます。酸素が少なくなっているからです。\n\n【よくあるまちがい】\n・「はく息には酸素がまったくない」と考えてしまう。減ってはいますが、約17％も残っています。人工呼吸ができるのはこのためです。\n・「はく息の白いものは水蒸気だ」と答えてしまう。水蒸気は目に見えません。白く見えるのは、冷やされてできた小さな水のつぶです。\n・ちっ素がふえると考えてしまう。ちっ素は体に取り入れられないので、ほとんど変わりません。',
