      '【何を聞かれているか】\n根の先近くに生えている細い毛の名前と、それがあることの利点です。\n\n【まず、根がしていること】\n根の仕事は3つあります。①体を支える ②水を吸う ③水にとけた養分を吸う。このうち②と③に直接かかわるのが根毛です。\n\n【なぜ細い毛がたくさんあると得なのか】\n水を吸えるのは、土とふれている表面の部分だけです。だから、ふれる面積が広いほどたくさん吸えます。\nただの棒のような根だと、外側のつるつるした面しか土にふれません。そこから細い毛が何千本も出ていると、その毛1本1本の表面がすべて土にふれるので、ふれる面積が何十倍にもなります。\n同じことは体の中のほかの場所でも使われています。\n・小腸の内側のひだや突起 …… 養分を吸う面積を広げる\n・肺の中の小さなふくろ …… 空気とふれる面積を広げる\n「たくさんに分けて面積をかせぐ」というのは、生き物が共通して使っているうまいやり方です。\n\n【ステップ1】どこに生えているか\n根毛は、根の先そのものではなく、先から少し後ろのところに生えています。いちばん先はこれから伸びていく大事な部分なので、根毛はまだありません。\n\n【ステップ2】土との関わり\n根毛は土のつぶのすきまに入りこんでいます。だから、植物を土から引きぬくと根に土がついてくるのです。根毛はとても細くて切れやすいので、植えかえのときに根を乱暴にあつかうと、水を吸えなくなって植物が弱ってしまいます。\n\n【答え】\n根毛。土とふれる面積を広くして、水や水にとけた養分をたくさん吸収できるようにするはたらき。\n\n【確かめ】\n発芽したばかりのカイワレダイコンやハツカダイコンを見ると、根のまわりに白いうぶ毛のようなものがびっしり生えているのが見えます。あれが根毛です。\n\n【よくあるまちがい】\n・「根の先に生えている」と書いてしまう。先ではなく、先から少し後ろです。\n・「土をつかんで体を支えるため」とだけ答えてしまう。支えるのは根全体の仕事で、根毛の一番のはたらきは吸収する面積を広げることです。\n・植えかえのときに根をきれいに洗ってしまう。根毛が切れて、植物が水を吸えなくなります。',
    examFrequency: 'medium',
