    question: '高いところから静かに手をはなしたボールが、落ちるにつれてだんだん速くなっていくのはなぜですか。また、高いところから落とすほど、床に置いた木片を遠くまで動かせるのはなぜですか。',
    answer: 'ボールには地球が引く力（重さ）が、落ちている間ずっと下向きにはたらき続け、速さをふやし続けるから。高いところから落とすほど床に着くときの速さが大きくなり、速い球ほど物を動かすはたらきが大きいから。',
    hint: '速さがふえるのは、力がはたらき続けているから。高さ→速さ→木片の動く距離、の順につながる。',
    explanation: '【解説】\n物体の速さを変えるには力が必要。落ちているボールには地球が引く力がずっと下向きにはたらいているので、速さはふえ続ける（1秒ごとに同じだけ速くなる）。\n\n【高さと速さ】\n高いところから落とすほど、力がはたらく時間が長いので、床に着くときの速さは大きくなる。ただし速さは高さに比例するのではなく、高さが4倍で速さが2倍、9倍で3倍になる。\n\n【木片を動かす距離】\n床の木片に球を当てると、木片が動く距離は\n・球を放す高さに比例する（高さ2倍で距離2倍）\n・球の重さに比例する（重さ2倍で距離2倍）\n・球の速さで見ると、速さ×速さに比例する（速さ2倍で距離4倍）\n「高さ4倍→速さ2倍→距離4倍」とつながっていて、つじつまが合う。\n\n【ふりこでも同じ】\nふりこのおもりは、いちばん低いところで最も速く、両はしで一瞬止まる。高いところで放すほど、最下点での速さは大きい。\n\n【よくあるまちがい】\n「落ちる速さは重さで決まる」と考えるミス。空気の抵抗がなければ、重い球も軽い球も同じ速さで落ちる。ちがうのは、当たったときに物を動かすはたらき（重い球ほど大きい）。',
