      '【何を聞かれているか】\n言葉がよく似ている「受粉」と「受精」を、区別して説明する問題です。どちらも植物が種子をつくるために必要ですが、起こる場所も順番もちがいます。\n\n【まず、花のつくりを思い出す】\n・おしべ …… 先のやく で花粉をつくる\n・めしべ …… 先を柱頭、根もとのふくらみを子ぼうといい、子ぼうの中にはいしゅが入っている\nはいしゅの中に、たまご（卵）があります。\n\n【ステップ1】受粉 ＝ 花粉が柱頭につくこと\nおしべでできた花粉が、こん虫や風、鳥などに運ばれて、めしべの先の柱頭につきます。これが受粉です。\n柱頭はねばねばしていたり、細かい毛が生えていたりして、花粉がつきやすくなっています。\nここで大事なのは、受粉はまだ「くっついただけ」だということです。この時点では、種子はできていません。\n\n【ステップ2】受精 ＝ 花粉から出たものが卵とくっつくこと\n柱頭についた花粉からは、細いくだ（花粉管）がのびます。このくだはめしべの中を下へ下へとのびていき、子ぼうの中のはいしゅまで届きます。そして、花粉から来たものと、はいしゅの中の卵がくっついて1つになります。これが受精です。\n\n【ステップ3】受精のあと\n受精が起こると\n・はいしゅ → 種子 になる\n・子ぼう → 実（果実）になる\nという変化が起こります。だから、受粉しただけで受精しなかった花は、実をつけずに落ちてしまいます。\n\n【答え】\n受粉：花粉がめしべの柱頭につくこと（花の外側・先に起こる）\n受精：花粉から出たものがめしべの中を通って、はいしゅの中の卵とくっつくこと（花の内側の奥・あとで起こる）\n\n【確かめ】\nカボチャやキュウリを育てるとき、人の手で花粉をめしべにつける「人工受粉」をすることがあります。受粉させた花だけが実になり、させなかった花は落ちてしまいます。受粉が実のできる出発点で、そのあとに受精が続いていることが確かめられます。\n\n【よくあるまちがい】\n・受粉と受精を同じ意味だと思ってしまう。順番は必ず「受粉 → 受精」です。\n・「受粉すれば必ず実ができる」と考えてしまう。受粉しても受精まで進まないことがあります。\n・種子ができる場所と実になる場所を取りちがえる。はいしゅ→種子、子ぼう→実、です。',
