    explanation: '【何を聞かれているか】\n光と音に共通する2つの性質を、例とセットで説明する問題です。\n\n【反射】\n・光：鏡に当たった光は、境界に垂直な線を真ん中にして同じ角度ではね返る（入射角＝反射角）。鏡の像は鏡について対称の位置に見える。\n・音：山や建物に当たった音がもどってくるのがやまびこ。音は往復するので、距離を出すときは（音速×時間）÷2。\n\n【屈折】\n・光：空気→水では速さがおそくなり、境界に垂直な線に近づく向きに曲がる。水→空気では遠ざかる向きに曲がる。水中の棒が曲がって見える、水中の物が浅く見える、虫めがねで光が集まる、はすべて屈折。\n・音：気温が高いほど音は速い。夜は地面近くの空気が冷えて音がおそくなり、上のほうが速いので音は下へ曲がる。だから夜は遠くの音がよく聞こえる。\n\n【よくあるまちがい】\n「屈折は光だけの性質」と考えるミス。音も速さが変わるところで曲がる。反射も屈折も、光と音に共通。',
